// Generated by Pen to Ink.
#include "NarrativeDemoGameMode.h"
#include "NarrativeBridgeComponent.h"
#include "NarrativeCuePlayer.h"
#include "NarrativeStoryPanel.h"
#include "Engine/World.h"
#include "EngineUtils.h"

void ANarrativeDemoGameMode::BeginPlay()
{
    Super::BeginPlay();
    // A level that already has the story (Tools → Pen to Ink → Add … to the Level) needs no other.
    for (TActorIterator<AActor> It(GetWorld()); It; ++It)
        if (It->FindComponentByClass<UNarrativeBridgeComponent>()) return;
    AActor* Actor = GetWorld()->SpawnActor<AActor>();
    if (!Actor) return;
    auto Attach = [Actor](UActorComponent* C)
    {
        Actor->AddInstanceComponent(C);
        C->RegisterComponent();
    };
    // The story first, so the panel finds it.
    Attach(NewObject<UNarrativeBridgeComponent>(Actor, TEXT("Story")));
    Attach(NewObject<UNarrativeCuePlayerComponent>(Actor, TEXT("CuePlayer")));
    Attach(NewObject<UNarrativeStoryPanelComponent>(Actor, TEXT("StoryPanel")));
}
